        {
          "kind": "formula",
          "value": "\\Delta"
        },
        {
          "kind": "text",
          "value": "."
        }
      ]
    },
    {
      "id": "text_ex3_s_final",
      "segments": [
        {
          "kind": "text",
          "value": "Le soluzioni dell'equazione sono "
        },
        {
          "kind": "formula",
          "value": "x_1 = \\frac{-3 - \\sqrt{17}}{4}"
        },
        {
          "kind": "text",
          "value": " e "
        },
        {
          "kind": "formula",
          "value": "x_2 = \\frac{-3 + \\sqrt{17}}{4}"
        },
        {
          "kind": "text",
          "value": "."
        }
      ]
    },
    {
      "id": "text_ex4_q",
      "segments": [
        {
          "kind": "text",
          "value": "Risolvi la seguente disequazione di secondo grado:"
