    },
    {
      "id": "text_ex5_s_step2",
      "segments": [
        {
          "kind": "text",
          "value": "Consideriamo l'equazione associata "
        },
        {
          "kind": "formula",
          "value": "4x^2 - 6x + 1 = 0"
